const menu=document.querySelector('.menu-toggle');const nav=document.querySelector('#nav');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu?.getAttribute('aria-expanded')==='true'){menu.setAttribute('aria-expanded','false');nav.classList.remove('open');menu.focus()}});
const form=document.querySelector('#quote-form');if(form){const choice=new URLSearchParams(location.search).get('service');const labels={remodeling:'Home remodeling',construction:'Construction & decks','painting-drywall':'Painting & drywall','flooring-tile':'Flooring & tile'};if(labels[choice])form.elements.service.value=labels[choice];form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const d=new FormData(form);const body=['Name: '+d.get('name'),'Email: '+d.get('email'),'Phone: '+d.get('phone'),'Location: '+d.get('location'),'Service: '+d.get('service'),'','Project details:',d.get('message')].join('\n');location.href='mailto:cpsprestigeconstruction@gmail.com?subject='+encodeURIComponent('Website quote request: '+d.get('service'))+'&body='+encodeURIComponent(body);document.querySelector('#form-status').textContent='Your email app should open with your request. Review it and press Send. If it does not open, call 404-542-8325 or email us directly.'})}

const invoiceForm=document.querySelector('#invoice-demo');invoiceForm?.addEventListener('submit',e=>{e.preventDefault();if(!invoiceForm.reportValidity())return;document.querySelector('#invoice-label').textContent='Invoice '+invoiceForm.elements.invoice.value;document.querySelector('#invoice-preview').hidden=false;document.querySelector('#payment-status').textContent='';});document.querySelector('#card-preview')?.addEventListener('click',()=>{document.querySelector('#payment-status').textContent='Demo preview only. A secure card-payment page will open here once the owner connects a payment provider. No payment has been made.';});
const reviewForm=document.querySelector('#review-demo');reviewForm?.addEventListener('submit',e=>{e.preventDefault();if(!reviewForm.reportValidity())return;const d=new FormData(reviewForm);document.querySelector('#review-status').textContent='Review preview: '+d.get('rating')+' / 5 — '+d.get('review')+' — Demo only: nothing has been posted or saved.';});
